-- Seed the approved 'Build Your Own Apps with Claude Code' agentic flyer (TGS-2025052468)
-- as a PENDING proposal in the pipeline. SG-gated: inserts only where the blast pipeline is
-- enabled (mmd_marketing/newsletter/blast_enabled=1), so country instances are untouched.
-- review_token stays NULL: Cron_Flyer::followUp() (hourly) emails both managers the signed
-- Approve / Request-changes links. Idempotent via NOT EXISTS on an open proposal for the course.
INSERT INTO newsletters (country_code, template_key, title, subject, preview_text, course_pids, body_html, status, review_status, is_auto) SELECT 'SG', 'agentic_flyer', 'Build Your Own Apps with Claude Code', 'Build Your Own Apps with Claude Code — up to 70% SkillsFuture funded', 'Turn your app ideas into working apps in one day. Check your funding — pay as little as S$0.', e.entity_id, UNHEX(''), 'draft', 'pending', 0 FROM catalog_product_entity e WHERE e.sku = 'TGS-2025052468' AND EXISTS (SELECT 1 FROM core_config_data c WHERE c.path = 'mmd_marketing/newsletter/blast_enabled' AND c.value = '1') AND NOT EXISTS (SELECT 1 FROM newsletters n WHERE n.template_key = 'agentic_flyer' AND n.course_pids = CAST(e.entity_id AS CHAR) AND n.review_status IN ('pending','changes_requested','approved'));
